.onb-havale-indirim{
background:#f3fff3;
border:1px solid #2e7d32;
padding:10px 14px;
margin-top:8px;
border-radius:6px;
color:#2e7d32;
font-weight:700;
font-size:14px;
}

.onb-indirim-tutar{
font-size:20px !important;
font-weight:700;
}

/* adet kutusu */

.single-product form.cart .quantity{
display:flex;
align-items:center;
margin-right:10px;
}

.single-product form.cart .quantity button,
.single-product form.cart .quantity input{
height:46px;
}

/* + - butonları */

.single-product form.cart .quantity button{
background:#FFAA00;
border:none;
color:#000;
width:40px;
font-weight:700;
}

/* Ortak tasarım */
.single_add_to_cart_button,
.onb-hemen-al-btn{
color:#fff !important;
font-weight:600 !important;
border-radius:10px !important;
padding:12px 26px;
text-decoration:none;
display:inline-flex;
align-items:center;
justify-content:center;
font-family:'Poppins', sans-serif !important;
font-size:14px;
letter-spacing:0.3px;
}

/* Satın Al */
.single_add_to_cart_button{
background:#FFAA00 !important;
}

/* Hemen Al */
.onb-hemen-al-btn{
background:#000 !important;
}nd:#000 !important;
}


/* hizalama */

.single-product form.cart{
display:flex;
align-items:center;
gap:10px;
}

/* öne çıkan bilgiler kutusu */

.woocommerce-product-details__short-description{
background:#f3f3f3;
padding:18px 20px;
border-radius:10px;
margin-top:15px;
}

/* başlık */

.woocommerce-product-details__short-description p:first-child{
font-weight:700;
margin-bottom:10px;
border-bottom:2px solid #FFAA00;
display:inline-block;
padding-bottom:4px;
}

/* liste */

.woocommerce-product-details__short-description ul{
list-style:none;
padding-left:0;
margin:0;
}

.woocommerce-product-details__short-description li{
position:relative;
padding-left:26px;
margin-bottom:6px;
}

/* turuncu tik */

.woocommerce-product-details__short-description li:before{
content:"✔";
position:absolute;
left:0;
top:0;
color:#FFAA00;
font-weight:700;
}

.onb-sku{
font-size:16px;
color:#000;
margin-bottom:10px;
}

.onb-sku .onb-kod{
color:#FFAA00;
font-weight:700;
font-size:17px;
}

/* MOBIL */

@media (max-width:768px){

/* başlık küçült */

.single-product .product_title{
font-size:18px !important;
line-height:1.3 !important;
margin-bottom:10px;
}

/* mobil sticky satın alma barı */

.single-product form.cart{
position:fixed;
bottom:0;
left:0;
width:100%;
background:#fff;
padding:10px;
display:flex;
align-items:center;
gap:8px;
z-index:9999;
box-shadow:0 -3px 12px rgba(0,0,0,0.15);
}

/* adet mobilde gizle */

.single-product form.cart .quantity{
display:none;
}

/* fiyat */

.price{
font-size:18px !important;
font-weight:700;
margin-right:auto;
}

/* SEPETE EKLE */

.single_add_to_cart_button{
background:#FFAA00 !important;
color:#fff !important;
border-radius:8px;
height:42px;
flex:1;
font-size:14px;
font-weight:700;
}

/* HEMEN AL */

.onb-hemen-al-btn{
background:#000 !important;
color:#fff !important;
border-radius:8px;
height:42px;
flex:1;
display:flex;
align-items:center;
justify-content:center;
text-decoration:none;
font-size:14px;
font-weight:700;
font-family:'Poppins', sans-serif !important;
}

/* sayfa altına boşluk */

body.single-product{
padding-bottom:80px;
}

/* ilgili ürünleri 2 sütun yap */

.related.products ul.products{
display:grid !important;
grid-template-columns:repeat(2,1fr);
gap:10px;
}

.related.products ul.products li.product{
width:100% !important;
margin:0 !important;
}

/* ürün başlığı */

.related.products .mkdf-product-list-title{
font-size:12px;
line-height:1.3;
max-height:34px;
overflow:hidden;
position:relative;
}

.related.products .mkdf-product-list-title a{
display:block;
overflow:hidden;
text-overflow:ellipsis;
display:-webkit-box;
-webkit-line-clamp:2;
-webkit-box-orient:vertical;
}

/* gerçek üç nokta */

.related.products .mkdf-product-list-title:after{
content:"...";
position:absolute;
right:0;
bottom:0;
background:#fff;
padding-left:4px;
}

/* kategori yazısı */

.related.products ul.products li.product .posted_in{
font-size:11px;
}

/* havale eft kutusu küçült */

.related.products ul.products li.product .onb-havale-indirim{
font-size:9px !important;
padding:3px 6px !important;
margin-top:4px;
line-height:1.2;
}

/* indirim tutarı küçült */

.related.products ul.products li.product .onb-indirim-tutar{
font-size:10px !important;
font-weight:600;
}

}
/* adet kutusu tasarım */

.quantity{
display:inline-flex;
align-items:center;
border:2px solid #eee;
border-radius:8px;
overflow:hidden;
background:#fff;
}

.quantity input.qty{
width:50px !important;
border:none !important;
text-align:center;
font-weight:600;
font-size:16px;
color:#000 !important; /* rakam siyah */
background:transparent;
}

.quantity .minus,
.quantity .plus{
padding:10px 14px;
font-size:18px;
font-weight:700 !important;
color:#f59e0b !important; /* turuncu */
cursor:pointer;
user-select:none;
}

.quantity .minus:hover,
.quantity .plus:hover{
background:#fff3e6;
}
/* ilgili ürün başlığı 2 satır sınırı */

.woocommerce ul.products li.product h4,
.woocommerce ul.products li.product .woocommerce-loop-product__title{

display:-webkit-box;
-webkit-line-clamp:2;
-webkit-box-orient:vertical;
overflow:hidden;

line-height:1.4;
max-height:2.8em;
}
@media(max-width:768px){

/* 4 sütun */
