}

/* FLASH ALANI ARKAPLAN */

.onb-flash-products{
background:linear-gradient(90deg,#ff2d2d 0%,#ff7a00 100%) !important;
padding:35px !important;
border-radius:18px !important;
}

/* ÜRÜN KARTI */

.onb-flash-products .onb-flash-item{
background:#f3f3f3 !important;
border-radius:16px !important;
padding:22px !important;
text-align:center !important;
transition:.25s !important;
position:relative !important;
}

.onb-flash-products .onb-flash-item:hover{
transform:translateY(-6px) scale(1.02) !important;
box-shadow:0 18px 40px rgba(0,0,0,.15) !important;
}

/* GÖRSEL */

.onb-flash-products .onb-flash-item img{
max-height:170px !important;
object-fit:contain !important;
margin-bottom:12px !important;
}

/* BAŞLIK 2 SATIR */

.onb-flash-products .onb-flash-item h3{
font-size:14px !important;
line-height:1.35 !important;
height:38px !important;
overflow:hidden !important;
display:-webkit-box !important;
-webkit-line-clamp:2 !important;
-webkit-box-orient:vertical !important;
text-overflow:ellipsis !important;
color:#222 !important;
}

/* FLASH ALANI */

.onb-flash-products{
background:linear-gradient(90deg,#ff2d2d 0%,#ff7a00 100%) !important;
padding:35px;
border-radius:18px;
}

/* FLASH BAŞLIK */

.onb-flash-title{
display:inline-block;
background:#fff;
padding:8px 18px;
border-radius:30px;
font-weight:600;
margin-bottom:20px;
}

/* ÜRÜN KARTI */

.onb-flash-item{
background:#efefef;
border-radius:16px;
padding:22px;
text-align:center;
position:relative;
transition:.25s;
}

.onb-flash-item:hover{
transform:translateY(-6px);
box-shadow:0 15px 35px rgba(0,0,0,.15);
}

/* ÜRÜN GÖRSEL */

.onb-flash-item img{
max-height:170px;
object-fit:contain;
margin-bottom:12px;
}

/* ÜRÜN BAŞLIK 2 SATIR */

.onb-flash-item h3{
font-size:14px;
line-height:1.35;
height:38px;
overflow:hidden;
display:-webkit-box;
-webkit-line-clamp:2;
-webkit-box-orient:vertical;
text-overflow:ellipsis;
color:#222;
}

/* FLASH BALONCUĞU */

.onb-flash-badge{
position:absolute;
top:12px;
left:12px;

width:78px;
height:78px;

display:flex;
flex-direction:column;
align-items:center;
justify-content:center;

border-radius:50%;

background:linear-gradient(135deg,#ff2d2d,#ff7a00);
color:#fff;

font-family:'Poppins',sans-serif;
font-weight:700;
font-size:12px;
text-align:center;

box-shadow:
0 6px 16px rgba(0,0,0,.25),
inset 0 4px 8px rgba(255,255,255,.25);

animation:flashPulse 2.5s ease-in-out infinite;
}

/* FİYAT KUTUSU */

.onb-price-box{
margin-top:14px;
padding:14px;
border-radius:12px;
background:rgba(255,170,0,0.06);
position:relative;
}

/* GERÇEK BORDER ANİMASYONU */

.onb-price-box::before{
content:"";
position:absolute;
inset:0;
padding:2px;
border-radius:12px;
background:linear-gradient(90deg,transparent,#FFAA00,transparent);
-webkit-mask:
linear-gradient(#000 0 0) content-box,
linear-gradient(#000 0 0);
-webkit-mask-composite:xor;
mask-composite:exclude;
animation:borderMove 3s linear infinite;
}

@keyframes borderMove{
0%{background-position:-200px}
100%{background-position:200px}
}

/* ESKİ FİYAT */

.old-price{
display:block;
color:#000;
font-weight:600;
text-decoration:line-through;
margin-bottom:4px;
}

/* İNDİRİM ORANI */

.discount{
display:block;
color:#FFAA00;
font-weight:700;
}

/* YENİ FİYAT */

.new-price{
display:block;
color:#FFAA00;
font-size:19px;
font-weight:700;
}
/* FLASH ÜRÜN GRID */

.onb-flash-slider{
display:grid;
grid-template-columns:repeat(4,1fr);
gap:24px;
margin-top:20px;
}

@media(max-width:1100px){
