grid-template-columns:1fr;
}
}
/* KART İÇ DÜZENİ */

.onb-flash-item{
display:flex;
flex-direction:column;
align-items:center;
justify-content:flex-start;
}

/* ESKİ FİYAT */

.old-price{
text-align:center;
margin-top:6px;
margin-bottom:6px;
}

/* FİYAT KUTUSU */

.onb-price-box{
display:flex;
justify-content:space-between;
align-items:center;
width:85%;
margin:10px auto;
padding:12px 14px;
}

/* SOL METİN */

.discount-text{
display:flex;
flex-direction:column;
line-height:1.2;
text-align:left;
}

/* SAĞ FİYAT */

.discount-price{
font-size:18px;
font-weight:700;
color:#FFAA00;
margin-left:10px;
}

/* BUTON SATIRI */

.onb-cart-row{
display:flex;
align-items:center;
justify-content:space-between;
width:85%;
margin:10px auto 0;
gap:8px;
}

/* SEPETE EKLE */

.onb-add-cart{
flex:1;
display:flex;
align-items:center;
justify-content:center;
background:#f6f6f6;
border:1px solid #dcdcdc;
padding:10px 14px;
border-radius:10px;

font-family:'Poppins',sans-serif;
font-size:15px;
font-weight:600;
color:#000;

text-decoration:none;
transition:.2s;
}

.onb-add-cart:hover{
background:#eeeeee;
}

/* HOVER */

.onb-add-cart:hover{
background:#eeeeee;
border-color:#cfcfcf;
}

/* WISHLIST */

.onb-wishlist{
width:42px;
height:42px;
display:flex;
align-items:center;
justify-content:center;
border:1px solid #dcdcdc;
border-radius:10px;
background:#fff;
font-size:18px;
text-decoration:none;
color:#666;
transition:.2s;
}

.onb-wishlist:hover{
background:#f5f5f5;
color:#ff4d4d;
border-color:#cfcfcf;
}


/* GOOGLE FONT */
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap');

/* TOPBAR GENEL */
.onb-topbar{
background:#000;
color:#fff;
width:100%;
font-family:'Poppins',sans-serif;
font-size:14px;
}

/* TOPBAR CONTAINER */
.onb-topbar-inner{
max-width:1200px;
margin:auto;
display:flex;
align-items:center;
justify-content:space-between;
height:36px;
}

/* SOL MENÜ */
.onb-topbar-left ul{
display:flex;
list-style:none;
margin:0;
padding:0;
}

/* MENÜ ELEMANI */
.onb-topbar-left ul li{
margin-right:15px;
padding-right:15px;
border-right:1px solid rgba(255,255,255,0.35);
}

/* SON MENÜDE ÇİZGİ YOK */
.onb-topbar-left ul li:last-child{
border-right:none;
}

/* MENÜ LİNK */
.onb-topbar-left ul li a{
color:#fff;
text-decoration:none;
font-weight:500;
letter-spacing:0.3px;
}

/* GENEL GRID HİZASI */
.onb-topbar-inner,
.onb-middle-inner,
.mkdf-page-header .mkdf-menu-area-inner{
max-width:1200px;
margin:auto;
padding:0 15px;
}

.onb-middle-inner{
