height:60px;
width:auto;
}

/* ARAMA ALANI */
.onb-middle-search form{
display:flex;
max-width:520px;
margin:auto;
}

.onb-middle-search input{
width:100%;
padding:11px 15px;
border:1px solid #ddd;
border-right:0;
border-radius:30px 0 0 30px;
height:44px;
