@media (max-width: 768px){

/* slider padding fix */
.onb-flash-slider {
    padding: 0 10px;
}

/* kart genişliği düzelt */
.onb-flash-slider .swiper-slide {
    width: 50% !important;
}

/* iç kart */
.onb-flash-item {
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

/* görsel düzgün otursun */
.onb-flash-item img {
    width: 100%;
    height: auto;
}

/* fiyat alanı taşmasın */
.onb-price-box {
    width: 100%;
}

/* buton sabit dursun */
.onb-cart-row {
    margin-top: auto;
}

/* badge taşma fix */
.onb-flash-badge {
    font-size: 11px;
    padding: 4px 6px;
}

}

/* FONT + HARF */
.onb-price-box,
.onb-price-box * {
  font-family: 'Poppins', sans-serif !important;
  text-transform: none !important;
}

/* FİYAT BLOĞU */
.onb-price-box {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 100%;
}

.onb-old-price {
  font-size: 13px;
  color: #8a8a8a;
  text-decoration: line-through;
}

/* ANA KUTU */
.onb-discount-box {
  display: grid;
  grid-template-columns: auto auto; /* 🔥 sadece 2 sütun */
  align-items: center;
  justify-content: start; /* 🔥 space-between KALDIRILDI */

  gap: 8px; /* sütun arası boşluk */

  padding: 6px 10px;

  border: 2px solid #f59e0b;
  border-radius: 10px;
  background: #fff7ed;

  width: fit-content; /* 🔥 içerik kadar geniş */
  max-width: 100%;
}

/* SOL BLOK */
.onb-discount-left {
  display: flex;
  flex-direction: column;
  line-height: 1.05;
  color: #f59e0b;
}

/* SATIRLAR */
.onb-discount-left .line1 { font-size: 10px; }
.onb-discount-left .line2 { font-size: 15px; font-weight: 700; }
.onb-discount-left .line3 { font-size: 10px; }

/* SAĞ FİYAT */
.onb-new-price {
  font-size: 14px;
  font-weight: 700;
  color: #f59e0b;

  white-space: nowrap;
}
/* SAĞ */
.onb-new-price {
  font-size: 14px;
  font-weight: 700;
  color: #f59e0b;
  text-align: right;
  white-space: nowrap;
}

/* BUTON */
/* SEPETE EKLE BUTON */
.onb-add-to-cart {
  width: 100%;
  margin-top: 6px; /* 🔥 boşluğu azalttık */
  padding: 8px;

  background: linear-gradient(135deg, rgba(34,197,94,0.12), rgba(34,197,94,0.05));
  border: 2px solid #22c55e;
  border-radius: 10px;

  color: #22c55e;
  font-family: 'Poppins', sans-serif;
  font-size: 13px;
  font-weight: 600;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;

  cursor: pointer;
  transition: 0.2s;
}

/* ikon (yazıyla aynı renk) */
.onb-add-to-cart::before {
  content: "";
  width: 14px;
  height: 14px;
  background: currentColor; /* 🔥 yazıyla aynı renk */
  mask: url('https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.5/icons/cart.svg') no-repeat center;
  -webkit-mask: url('https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.5/icons/cart.svg') no-repeat center;
}

/* hover */
.onb-add-to-cart:hover {
  background: #22c55e;
  color: #fff;
}
/* MARKA */
.onb-brand {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: #111;
  margin-bottom: 2px;
}

/* ÜRÜN ADI */
.onb-name {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;

  overflow: hidden;
  text-overflow: ellipsis;

  font-size: 13px;
  color: #444;
  line-height: 1.3;
}

.product {
    position: relative;
}

.woocommerce-checkout .woocommerce {
    display: grid;
    grid-template-columns: 1.2fr 0.8fr;
    gap: 40px;
}

.woocommerce-checkout form.checkout {
    display: contents;
}

#customer_details {
    grid-column: 1;
}

#order_review {
    grid-column: 2;
    background: #fff7f0;
    padding: 20px;
    border-radius: 12px;
    border: 1px solid #ffe2c7;
}
button,
.button,
#place_order {
    background: #ff7a00 !important;
    border-color: #ff7a00 !important;
    color: #fff !important;
}

button:hover {
    background: #e66a00 !important;
}

.woocommerce-checkout h3 {
    color: #ff7a00;
}
add_filter('woocommerce_checkout_fields', function($fields){

    unset($fields['billing']['billing_company']);
    unset($fields['billing']['billing_address_2']);

    return $fields;

});
.woocommerce-checkout .woocommerce {
    display: grid !important;
    grid-template-columns: 1.3fr 0.7fr;
    gap: 40px;
    align-items: start;
}

.woocommerce-checkout form.checkout {
    display: contents !important;
}

#customer_details {
    grid-column: 1;
}

#order_review {
    grid-column: 2;
    position: sticky;
    top: 20px;
}
@media (max-width: 768px) {
    .woocommerce-checkout .woocommerce {
        grid-template-columns: 1fr;
    }

    #order_review {
        position: relative;
    }
}
/* TÜM CHECKOUT YAPISINI RESETLE */
.woocommerce-checkout .col2-set,
.woocommerce-checkout .col-1,
.woocommerce-checkout .col-2 {
    width: 100% !important;
    float: none !important;
}

/* ANA WRAPPER'I GRID YAP */
.woocommerce-checkout .woocommerce {
    display: flex !important;
    gap: 40px;
    align-items: flex-start;
}

/* SOL ALAN */
.woocommerce-checkout #customer_details {
    width: 65% !important;
}

/* SAĞ ALAN */
.woocommerce-checkout #order_review {
    width: 35% !important;
    position: sticky;
    top: 20px;
}
.woocommerce-form-coupon-toggle {
    display: none !important;
}
/* FONT */
body, input, button, select, textarea {
    font-family: 'Poppins', sans-serif;
}

/* KUPON - sadece stil (yer değiştirmez!) */
.checkout_coupon {
    margin-bottom: 15px;
}

.checkout_coupon input.input-text {
    width: 70%;
    padding: 10px;
    border-radius: 6px;
    border: 1px solid #ddd;
}

.checkout_coupon button.button {
    background: #ff7a00 !important;
    color: #fff !important;
    padding: 10px 15px;
    border-radius: 6px;
}

/* ÜRÜN GÖRSEL */
.woocommerce-checkout-review-order-table .product-name {
    display: flex;
    align-items: center;
    gap: 10px;
}

.woocommerce-checkout-review-order-table .product-name img {
    width: 45px;
    border-radius: 6px;
}
#order_review {
    float: none !important;
    display: block !important;
    width: 100% !important;
    clear: both;
}
/* ANA 2 KOLON */
.woocommerce-checkout form.checkout {
    display: flex !important;
    gap: 40px;
    align-items: flex-start;
}

/* SOL %60 */
.col2-set {
    width: 60% !important;
}

/* SAĞ %40 */
.onb-right {
    width: 40% !important;
}

/* SAĞ BLOK TAŞMASIN */
.onb-right #order_review {
    width: 100% !important;
}

/* MOBİL */
@media (max-width: 768px){

    /* ANA YAPI */
    .woocommerce-checkout form.checkout {
        display: block !important;
        width: 100%;
    }

    /* TÜM BLOKLARI TEK GENİŞLİK YAP */
    .col2-set,
    .onb-right {
        width: 92% !important;     /* TEK GENİŞLİK */
        max-width: 700px;
        margin-left: auto !important;
        margin-right: auto !important;
    }

    /* ALT ALTA MESAFE */
    .onb-right {
        margin-top: 25px;
    }

    /* İÇERİK TAŞMASIN */
    #order_review {
        width: 100% !important;
    }

    /* TABLO SABİT */
    #order_review table {
        width: 100% !important;
        table-layout: fixed;
    }

    /* METİN TAŞMA FIX */
    #order_review td,
    #order_review th {
        word-break: break-word;
    }

}
/* Ana sepet wrapper */
.woocommerce-cart .woocommerce {
    display: flex;
    gap: 30px;
    align-items: flex-start;
}

/* SOL - ÜRÜNLER */
.woocommerce-cart-form {
    width: 70%;
}

/* SAĞ - TOPLAM */
.cart-collaterals {
    width: 30%;
}

/* Sağ kutu tasarım */
.cart_totals {
    background: #fff7f0;
    border: 1px solid #ffe2c7;
    border-radius: 12px;
    padding: 20px;
}

/* Buton */
.checkout-button {
    background: #ff7a00 !important;
    color: #fff !important;
    border-radius: 8px;
    padding: 15px;
    width: 100%;
    text-align: center;
}
/* + - butonları */
.quantity .minus,
.quantity .plus {
    background: transparent !important;
    border: 1px solid #ff7a00;
    color: #ff7a00 !important;
    font-weight: 600;
    width: 32px;
    height: 32px;
}

/* hover */
.quantity .minus:hover,
.quantity .plus:hover {
    background: #ff7a00;
    color: #fff !important;
}
/* ürün sil linki */
.product-remove a {
    display: inline-block;
    padding: 6px 12px;
    background: rgba(255, 122, 0, 0.2);
    color: #fff !important;
    border-radius: 20px;
    font-size: 12px;
    text-decoration: none;
}

/* hover */
.product-remove a:hover {
    background: #ff7a00;
}
/* checkout butonu */
.checkout-button {
    background: #ff7a00 !important;
    color: #fff !important;
    border-radius: 30px;
    padding: 18px;
    font-weight: 700;
    text-transform: uppercase; /* BÜYÜK HARF */
    letter-spacing: 1px;
    text-align: center;
    border: none;
}

/* hover */
.checkout-button:hover {
    background: #e66d00 !important;
}

@media (max-width: 768px){

    .woocommerce-form-login-toggle {
        background: #fff3e8;
        padding: 12px;
        border-radius: 10px;
        margin-bottom: 15px;
        text-align: center;
    }

    .woocommerce-form-login-toggle a {
        color: #ff7a00;
        font-weight: 600;
    }

}
@media (max-width: 768px){

    /* Login toggle'ı gizle (üstteki alan) */
    .woocommerce-form-login-toggle {
        display: none !important;
    }

}
body.woocommerce-checkout .mkdf-grid-row,
body.woocommerce-checkout .mkdf-page-content-holder,
body.woocommerce-checkout .mkdf-grid-col-12 {
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
}
body.woocommerce-checkout form .form-row {
    width: 100% !important;
    float: none !important;
}

@media (max-width: 768px){
body.woocommerce-checkout input,
body.woocommerce-checkout select,
body.woocommerce-checkout textarea {
    width: 140% !important;
}

@media (max-width: 768px){

    /* Ana container sola yaslansın */
    body.woocommerce-checkout .woocommerce {
        width: 100% !important;
        max-width: 100% !important;
        margin-left: 0 !important;
        margin-right: auto !important;
        padding-left: 10px !important;
        padding-right: 5px !important;
    }

    /* MKDF grid boşluklarını kır */
    body.woocommerce-checkout .mkdf-page-content-holder,
    body.woocommerce-checkout .mkdf-grid-row {
        padding-left: 0 !important;
        padding-right: 5px !important;
        margin: 0 !important;
    }

    /* alignwide saçmalığını temizle */
    body.woocommerce-checkout .wp-block-group.alignwide {
        margin-left: 0 !important;
        margin-right: 0 !important;
        padding-left: 0 !important;
        padding-right: 5px !important;
    }

    /* Checkout kolonları */
    body.woocommerce-checkout .col2-set,
    body.woocommerce-checkout .woocommerce-checkout-review-order {
        width: 100% !important;
        max-width: 100% !important;
        margin: 0 !important;
    }

}

