.product-title,
.woocommerce-loop-product__title,
.mkdf-pl-title {

 /* 🔥 büyük harfleri düzelt */
 text-transform: lowercase !important;
}

/* sadece ilk harfleri büyüt */
.product-title::first-letter,
.woocommerce-loop-product__title::first-letter,
.mkdf-pl-title::first-letter {
 text-transform: uppercase;
}

/* 2 satır + ... */
.product-title,
.woocommerce-loop-product__title,
.mkdf-pl-title {

 display: -webkit-box;
 -webkit-line-clamp: 2; /* 🔥 2 satır */
 -webkit-box-orient: vertical;

 overflow: hidden;
